import{_ as a,o as t,c as s,a4 as i}from"./chunks/framework.DzJZdBQK.js";const k=JSON.parse('{"title":"Hbase Indexer - 教程","description":"","frontmatter":{"date":"2018-12-05T12:33:00","title":"Hbase Indexer - 教程","categories":["hbase","hbase indexer"],"tags":["hbase","hbase indexer"]},"headers":[{"level":2,"title":"启动Hbase Indexer（Start the HBase Indexer daemon）","slug":"启动hbase-indexer-start-the-hbase-indexer-daemon","link":"#启动hbase-indexer-start-the-hbase-indexer-daemon","children":[]},{"level":2,"title":"创建需要索引的表（Create a table to be indexed in HBase）","slug":"创建需要索引的表-create-a-table-to-be-indexed-in-hbase","link":"#创建需要索引的表-create-a-table-to-be-indexed-in-hbase","children":[]},{"level":2,"title":"添加索引器（Add an indexer）","slug":"添加索引器-add-an-indexer","link":"#添加索引器-add-an-indexer","children":[]},{"level":2,"title":"更新表内容（Update the table content）","slug":"更新表内容-update-the-table-content","link":"#更新表内容-update-the-table-content","children":[]}],"relativePath":"posts/bigdata/hbase-indexer/getting-start-tutorial.md","filePath":"posts/bigdata/hbase-indexer/getting-start-tutorial.md"}'),n={name:"posts/bigdata/hbase-indexer/getting-start-tutorial.md"};function l(o,e,h,d,r,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<p>This page explains how to start doing basic indexing in HBase. Before following this tutorial, make sure that the HBase Indexer and other required software is installed and running as explained in the <a href="https://github.com/NGDATA/hbase-indexer/wiki/Installation" target="_blank" rel="noreferrer">installation instructions</a>.</p><p>这篇解释如何在Hbase中开始基础索引。在开始教程之前，请确保Hbase Indexer和其他需要的软件已经<a href="./.html">安装</a>和运行。</p><p>At this point, HBase and Solr (in cloud mode) should be running, and the HBase Indexer should be unpacked in a directory (which we&#39;ll call $INDEXER_HOME). For this tutorial, it is assumed that the default example index schema is being used by Solr (as explained on the <a href="https://github.com/NGDATA/hbase-indexer/wiki/Installation" target="_blank" rel="noreferrer">installation page</a>).</p><p>此时，Hbasa和Solr（云模式）已经行行，并且Hbase Indexer已经解压到一个目录中（这是我们称为<code>$INDEXER_HOME</code>）。在这个教程中，我们假设用的是Solr的默认example索引（就像<a href="https://github.com/NGDATA/hbase-indexer/wiki/Installation" target="_blank" rel="noreferrer">安装</a>中说的那样）。</p><h2 id="启动hbase-indexer-start-the-hbase-indexer-daemon" tabindex="-1">启动Hbase Indexer（Start the HBase Indexer daemon） <a class="header-anchor" href="#启动hbase-indexer-start-the-hbase-indexer-daemon" aria-label="Permalink to &quot;启动Hbase Indexer（Start the HBase Indexer daemon）&quot;">​</a></h2><p>In a terminal, execute the following (assuming $INDEXER_HOME points to the directory where the hbase-indexer tar.gz distribution was unpacked).</p><p>在终端中，运行如下命令（假定<code>$INDEXER_HOME</code>指向hbase-indexer tar.gz解压的目录）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd $INDEXER_HOME</span></span>
<span class="line"><span>./bin/hbase-indexer server</span></span></code></pre></div><h2 id="创建需要索引的表-create-a-table-to-be-indexed-in-hbase" tabindex="-1">创建需要索引的表（Create a table to be indexed in HBase） <a class="header-anchor" href="#创建需要索引的表-create-a-table-to-be-indexed-in-hbase" aria-label="Permalink to &quot;创建需要索引的表（Create a table to be indexed in HBase）&quot;">​</a></h2><p>In the HBase shell, create a table. For this tutorial, we&#39;ll create a table named &quot;indexdemo-user&quot;, with a single column family named &quot;info&quot;. Note that the <code>REPLICATION_SCOPE</code> of the column family of the table must be set to 1.</p><p>在Hbase shell，创建一个表。在这里，我们创建一个“indexdemo-user”的表，有一个“info”的列簇。注意列簇的<code>REPLICATION_SCOPE</code>必须设置成1。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ hbase shell</span></span>
<span class="line"><span>hbase&gt; create &#39;indexdemo-user&#39;, { NAME =&gt; &#39;info&#39;, REPLICATION_SCOPE =&gt; &#39;1&#39; }</span></span></code></pre></div><h2 id="添加索引器-add-an-indexer" tabindex="-1">添加索引器（Add an indexer） <a class="header-anchor" href="#添加索引器-add-an-indexer" aria-label="Permalink to &quot;添加索引器（Add an indexer）&quot;">​</a></h2><p>Now we&#39;ll create an indexer that will index the the indexdemo-user table as its contents are updated.</p><p>现在我们创建一个索引器，在indexdemo-user表的内容被更新是他会进行索引。</p><p>In your favourite text editor, create a new xml file called indexdemo-indexer.xml, with the following content:</p><p>用你喜欢的编辑器，创建一个新的xml文件，命名为<code>indexdemo-indexer.xml</code>，添加如下内容：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;?</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xml</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">?&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">indexer</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> table</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;indexdemo-user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">field</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;firstname_s&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info:firstname&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">field</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lastname_s&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info:lastname&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">field</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;age_i&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info:age&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;int&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">indexer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>The above file defines three pieces of information that will be used for indexing, how to interpret them, and how they will be stored in Solr.</p><p>上面的文件定义了三个索引字段的信息，如何解析，如何在Solr中存储。</p><p>Next, create an indexer based on the created indexer xml file.</p><p>接下来，基于xml文件创建一个索引器。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./bin/hbase-indexer add-indexer -n myindexer -c indexdemo-indexer.xml \\</span></span>
<span class="line"><span>        -cp solr.zk=localhost:2181/solr -cp solr.collection=collection1</span></span></code></pre></div><p>Note that the above command assumes that ZooKeeper is running on localhost on port 2181, and that there is a Solr Core called &quot;collection1&quot; configured. If you are doing this tutorial on an existing HBase/Solr environment, you may need to use different settings.</p><p>注意上面的命令假设，ZooKeeper运行要本机的2181端口上，并且Solr Core已经创建了一个名为“collection1”的索引。如果你在一个现有的Hbase/Solr环境运行本教程，你需要修改配置。</p><h2 id="更新表内容-update-the-table-content" tabindex="-1">更新表内容（Update the table content） <a class="header-anchor" href="#更新表内容-update-the-table-content" aria-label="Permalink to &quot;更新表内容（Update the table content）&quot;">​</a></h2><p>In the HBase shell, try adding some data to the indexdemo-user table 在Hbase shell中，尝试给<code>indexdemo-user</code>添加一些数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hbase&gt; put &#39;indexdemo-user&#39;, &#39;row1&#39;, &#39;info:firstname&#39;, &#39;John&#39;</span></span>
<span class="line"><span>hbase&gt; put &#39;indexdemo-user&#39;, &#39;row1&#39;, &#39;info:lastname&#39;, &#39;Smith&#39;</span></span></code></pre></div><p>After adding this data, take a look in Solr (i.e. <a href="http://localhost:8983/solr/#/collection1/query" target="_blank" rel="noreferrer">http://localhost:8983/solr/#/collection1/query</a>). You should see a single document in Solr that has the firstname_s field set to &quot;John&quot;, and the lastname_s field set to &quot;Smith&quot;.</p><p>添加数据之后，来看一下Solr（i.e. <a href="http://localhost:8983/solr/#/collection1/quer%EF%BC%89%EF%BC%8C%E4%BD%A0%E5%BA%94%E8%AF%A5%E8%83%BD%E7%9C%8B%E5%88%B0%E4%B8%80%E4%B8%AA%E6%96%87%E6%A1%A3%EF%BC%8C%E8%BF%99%E4%B8%AA%E6%96%87%E6%A1%A3%E7%9A%84firstname_s%E5%AD%97%E6%AE%B5%E5%80%BC%E4%B8%BA%E2%80%9CJohn%E2%80%9D%EF%BC%8C%E5%90%8C%E6%97%B6lastname_s%E5%AD%97%E6%AE%B5%E5%80%BC%E4%B8%BA%E2%80%9CSmith%E2%80%9D%E3%80%82" target="_blank" rel="noreferrer">http://localhost:8983/solr/#/collection1/quer），你应该能看到一个文档，这个文档的firstname_s字段值为“John”，同时lastname_s字段值为“Smith”。</a></p><p>Note If you don&#39;t have autoCommit enabled in Solr, you won&#39;t be able to see the updated contents immediately in Solr. The demo environment has autoCommit enabled for a commit every second.</p><p><strong>注意</strong>如果没有开启<code>autoCommit</code>，你不会马上在Solr看到更新的内容。这例子的环境<code>autoCommit</code>已经开启并设置为每秒自动提交1次。</p><p>Now try updating the data you&#39;ve just added</p><p>现在尝试更新你刚才添加的数据</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hbase&gt; put &#39;indexdemo-user&#39;, &#39;row1&#39;, &#39;info:firstname&#39;, &#39;Jim&#39;</span></span></code></pre></div><p>And now check the content in Solr. The document&#39;s firstname_s field now contains the string &quot;Jim&quot;.</p><p>然后在Solr有检查内容。看下文档的firstname_s是不是变成了“Jim”</p><p>Finally, delete the row from HBase.</p><p>最后，删除Hbase的这条记录。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hbase&gt; deleteall &#39;indexdemo-user&#39;, &#39;row1&#39;</span></span></code></pre></div><p>You can now verify that the data has been deleted from Solr.</p><p>你可以验证下Solr中的数据是不是已经删除了。</p>`,42)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
